void tipc_sub_report_overlap ( struct tipc_subscription * sub , struct publication * p , u32 event , bool must ) { struct tipc_service_range * sr = & sub -> s . seq ; u32 filter = sub -> s . filter ; if ( ! tipc_sub_check_overlap ( sr , & p -> sr ) ) { return ; } if ( filter & TIPC_SUB_CLUSTER_SCOPE && p -> scope == TIPC_NODE_SCOPE ) { return ; } if ( filter & TIPC_SUB_NODE_SCOPE && p -> scope != TIPC_NODE_SCOPE ) { return ; } spin_lock ( & sub -> lock ) ; tipc_sub_send_event ( sub , p , event ) ; spin_unlock ( & sub -> lock ) ; } 